def transform(scores: dict, graph, question: str, question_date: str) -> dict:
    import math

    if not scores:
        return scores

    def get_prefix(turn_id):
        parts = turn_id.rsplit('#', 1)
        return parts[0] if len(parts) == 2 else turn_id

    def get_turn_idx(turn_id):
        parts = turn_id.rsplit('#', 1)
        try:
            return int(parts[1]) if len(parts) == 2 else 0
        except ValueError:
            return 0

    sorted_items = sorted(scores.items(), key=lambda x: x[1], reverse=True)
    n = len(sorted_items)

    prefix_counts = {}
    for tid, _ in sorted_items:
        p = get_prefix(tid)
        prefix_counts[p] = prefix_counts.get(p, 0) + 1

    prefix_rank = {}
    for tid, sc in sorted_items:
        p = get_prefix(tid)
        if p not in prefix_rank:
            prefix_rank[p] = 0
        prefix_rank[p] += 1

    prefix_seen = {}
    new_scores = {}

    all_score_vals = [s for _, s in sorted_items]
    max_score = all_score_vals[0] if all_score_vals else 1.0
    min_score = all_score_vals[-1] if all_score_vals else 0.0
    score_range = max_score - min_score if max_score != min_score else 1.0

    for rank, (tid, sc) in enumerate(sorted_items):
        p = get_prefix(tid)
        tidx = get_turn_idx(tid)

        if p not in prefix_seen:
            prefix_seen[p] = 0
        prefix_seen[p] += 1

        occurrence = prefix_seen[p]
        total_from_prefix = prefix_counts[p]

        diversity_penalty = 1.0
        if occurrence > 1:
            diversity_penalty = 1.0 / math.log(occurrence + 1)

        anchor_boost = 1.0
        if tidx == 0:
            anchor_boost = 1.15
        elif tidx <= 2:
            anchor_boost = 1.05

        isolation_boost = 1.0
        if total_from_prefix == 1:
            isolation_boost = 1.1

        rank_position = rank / max(n - 1, 1)

        mid_boost = 1.0
        if 0.2 <= rank_position <= 0.7:
            mid_boost = 1.0 + 0.12 * math.sin(math.pi * (rank_position - 0.2) / 0.5)

        combined = sc * diversity_penalty * anchor_boost * isolation_boost * mid_boost
        new_scores[tid] = combined

    return new_scores

import math

def transform(scores: dict, graph, question: str, question_date: str) -> dict:
    if not scores:
        return scores

    all_scores = list(scores.values())
    max_score = max(all_scores)
    min_score = min(all_scores)
    score_range = max_score - min_score if max_score != min_score else 1.0

    # Extract conversation prefix -> list of (turn_id, score, turn_index)
    prefix_scores = {}
    for turn_id, score in scores.items():
        parts = turn_id.rsplit('#', 1)
        if len(parts) == 2:
            prefix = parts[0]
            try:
                idx = int(parts[1])
            except ValueError:
                idx = 0
            if prefix not in prefix_scores:
                prefix_scores[prefix] = []
            prefix_scores[prefix].append((turn_id, score, idx))

    # For each prefix, find max score in that conversation
    prefix_max = {}
    for prefix, items in prefix_scores.items():
        prefix_max[prefix] = max(s for _, s, _ in items)

    # Compute mean and std for normalization reference
    mean_score = sum(all_scores) / len(all_scores)
    variance = sum((s - mean_score) ** 2 for s in all_scores) / len(all_scores)
    std_score = math.sqrt(variance) if variance > 0 else 1.0

    new_scores = {}
    for turn_id, score in scores.items():
        parts = turn_id.rsplit('#', 1)
        boost = 0.0

        if len(parts) == 2:
            prefix = parts[0]
            try:
                idx = int(parts[1])
            except ValueError:
                idx = 0

            conv_max = prefix_max.get(prefix, score)

            # Boost #0 turns (first turns) - they are frequently evidence
            if idx == 0:
                # Stronger boost for #0 turns, scaled by how high the conversation scores
                boost += 0.08 * (1.0 + conv_max)

            # Boost turns from conversations that have at least one high-scoring turn
            # This helps pull up lower-ranked turns from relevant conversations
            if conv_max > mean_score + 0.5 * std_score:
                # Conversation is relevant, boost all its turns slightly
                boost += 0.03 * conv_max

            # Compress scores toward mean slightly to reduce budget wall effect
            # Pull low scores up more than pulling high scores down
            if score < mean_score:
                compression_boost = 0.15 * (mean_score - score)
                boost += compression_boost

        new_scores[turn_id] = score + boost

    return new_scores
